CREATE OR REPLACE FUNCTION chk_k1() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c3 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c3 IS NOT NULL AND c1=NEW.c1 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k1 violated'; END IF;
  IF (NEW.c3 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c3 IS NOT NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k1 violated'; END IF;
  RETURN NEW; END $$;
